#ifndef MD_INTERCEPTION_ROUTE_H
#define MD_INTERCEPTION_ROUTE_H
#include "interception_program.h"
#include "pid_filter_program.h"
#include "seccomp_program.h"
#include <stdatomic.h>

enum { MD_ROUTE_PID=1,MD_ROUTE_SIGNALS=2,MD_ROUTE_ADMITTED_KERNEL=4 };
/* All programs are generated by the same owners as the installed filters.
 * Prepared once per bootstrap ABI, never rebuilt for a syscall. */
struct md_interception_routes {
    struct md_interception_program base,signals;
    struct md_pid_filter_program pid;
    struct md_seccomp_cache base_allow,signal_allow,pid_allow;
    struct {
        struct md_fd_filter_program all,one;
        struct md_seccomp_cache allow;
        unsigned parameters;
        uint16_t parameter[32];
    } fd[MD_FD_SELECTOR_KINDS];
};
/* Routing hints only, not guest-seccomp authority. Installed selectors grow
 * monotonically; a concurrent older hint falls back to the original kernel
 * call, where the newer selector remains authoritative. */
struct md_interception_route_view {
    atomic_uint active,all,flags;
    atomic_uint_fast64_t bits[MD_FD_SELECTOR_KINDS][MD_FD_SELECTOR_WORDS];
};
int md_interception_routes_init(struct md_interception_routes *,const struct md_interception_abi *);
int md_interception_routes_eval(const struct md_interception_routes *,const struct md_fd_selector_view *,
    unsigned flags,const struct seccomp_data *,uint32_t *);
void md_interception_route_publish(struct md_interception_route_view *,const struct md_fd_selector_view *,unsigned);
int md_interception_route_eval(const struct md_interception_routes *,const struct md_interception_route_view *,
    const struct seccomp_data *,uint32_t *);
#endif
